      "openapi": "3.1.0",
      "info": {
        "title": "Meridian Telemetry \u2014 fleet vehicle GPS & sensor ingest platform for logistics operators API",
        "version": "1.0.0",
        "description": "Meridian Fleet API: ingests vehicle telemetry batches, exposes trip rollups, and commits processed batches into the warehouse. Used by logistics integrators wiring dashboards and ETL pipelines."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
