          "post": {
            "summary": "OAuth client_credentials",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/batches": {
          "get": {
            "summary": "List telemetry batches (throttled)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/batches/{id}": {
          "get": {
            "summary": "Get batch detail",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/batches/{id}/commit": {
          "post": {
            "summary": "Commit a batch",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/trips/rollup": {
          "get": {
            "summary": "Trip rollup (region-gated)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/batches/{id}/commit": {
          "post": {
            "summary": "DEPRECATED commit",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
  "updated_at": "2026-06-30T04:11:54.256649+00:00"
}

